import { locate as locateCharacter, type Location } from 'locate-character';

export { type Location };

export function locate(
	source: string,
	search: string | number,
	options?: { offsetColumn?: number; offsetLine?: number; startIndex?: number }
): Location {
	const location = locateCharacter(source, search, options);
	if (!location) {
		throw new Error(`Unable to locate ${JSON.stringify(search)} in source code.`);
	}
	return location;
}

