const base = 64;

export function toBase64(value: number): string {
	let outString = '';
	do {
		const currentDigit = value % base;
		value = (value / base) | 0;
		outString = chars[currentDigit] + outString;
	} while (value !== 0);
	return outString;
}
","function spaces(index: number): string {
	let result = '';
	while (index--) result += ' ';
	return result;
}

function tabsToSpaces(value: string): string {
	return value.replace(/^\t+/, match => match.split('\t').join('  '));
}

const LINE_TRUNCATE_LENGTH = 120;
const MIN_CHARACTERS_SHOWN_AFTER_LOCATION = 10;
const ELLIPSIS = '...';

export default function getCodeFrame(source: string, line: number, column: number): string {
	let lines = source.split('\n');
	// Needed if a plugin did not generate correct sourcemaps
	if (line > lines.length) return '';
	const maxLineLength = Math.max(
		tabsToSpaces(lines[line - 1].slice(0, column)).length +
			MIN_CHARACTERS_SHOWN_AFTER_LOCATION +
			ELLIPSIS.length,
		LINE_TRUNCATE_LENGTH
	);

	const frameStart = Math.max(0, line - 3);
	let frameEnd = Math.min(line + 2, lines.length);

	lines = lines.slice(frameStart, frameEnd);
	while (!/\S/.test(lines[lines.length - 1])) {
		lines.pop();
		frameEnd -= 1;
	}

	const digits = String(frameEnd).length;

	return lines
		.map((sourceLine, index) => {
			const isErrorLine = frameStart + index + 1 === line;

			let lineNumber = String(index + frameStart + 1);
			while (lineNumber.length < digits) lineNumber = ` ${lineNumber}`;

			let displayedLine = tabsToSpaces(sourceLine);
			if (displayedLine.length > maxLineLength) {
				displayedLine = `${displayedLine.slice(0, maxLineLength - ELLIPSIS.length)}${ELLIPSIS}`;
			}
			if (isErrorLine) {
				const indicator =
					spaces(digits + 2 + tabsToSpaces(sourceLine.slice(0, column)).length) + '^';
				return `${lineNumber}: ${displayedLine}\n${indicator}`;
			}

			return `${lineNumber}: ${displayedLine}`;
		})
		.join('\n');
}
","/** @typedef {import('./types').Location} Location */

/**
 * @param {import('./types').Range} range
 * @param {number} index
 */
function rangeContains(range, index) {
	return range.start <= index && index < range.end;
}

/**
 * @param {string} source
 * @param {import('./types').Options} [options]
 */
export function getLocator(source, options = {}) {
	const { offsetLine = 0, offsetColumn = 0 } = options;

	let start = 0;
	const ranges = source.split('\n').map((line, i) => {
		const end = start + line.length + 1;

		/** @type {import('./types').Range} */
		const range = { start, end, line: i };

		start = end;
		return range;
	});

	let i = 0;

	/**
	 * @param {string | number} search
	 * @param {number} [index]
	 * @returns {Location | undefined}
	 */
	function locator(search, index) {
		if (typeof search === 'string') {
			search = source.indexOf(search, index ?? 0);
		}

		if (search === -1) return undefined;

		let range = ranges[i];

		const d = search >= range.end ? 1 : -1;

		while (range) {
			if (rangeContains(range, search)) {
				return {
					line: offsetLine + range.line,
					column: offsetColumn + search - range.start,
					character: search
				};
			}

			i += d;
			range = ranges[i];
		}
	}

	return locator;
}

/**
 * @param {string} source
 * @param {string | number} search
 * @param {import('./types').Options} [options]
 * @returns {Location | undefined}
 */
export function locate(source, search, options) {
	return getLocator(source, options)(search, options && options.startIndex);
}
